describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy always returns 0, so the sum is just the percentage
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // 10% of 5000 = 500 + 200 = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially against remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining = 9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900, remaining = 8100
        ],
        "chain",
      );
      // Total discount = 1000 + 900 = 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("stops discounting when remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800), // takes 800 from 1000, remaining = 200
          new FixedAmountDiscountPolicy(500), // wants 500, only 200 left → takes 200
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("ordering matters in chain mode", () => {
      // fixed-first then percentage
      const fixedFirst = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000), // 1000 off 10000 → remaining 9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900
        ],
        "chain",
      );
      // percentage-first then fixed
      const pctFirst = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000 → remaining 9000
          new FixedAmountDiscountPolicy(1000), // 1000 off 9000
        ],
        "chain",
      );
      // fixedFirst: 1000 + 900 = 1900
      expect(fixedFirst.computeDiscountCents(10000)).toBe(1900);
      // pctFirst: 1000 + 1000 = 2000
      expect(pctFirst.computeDiscountCents(10000)).toBe(2000);
    });
  });
});
"}

