import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine, Product } from "../src/product.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

const line = (qty: number, overrides: Partial<Product> = {}): CartLine => ({
  product: product(overrides),
  quantity: qty,
});

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [5000, "FR"],
    [-100, "GB"],
  ])("returns 0 for taxable=%i region=%s", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it.each([-0.01, 1.01, NaN, Infinity])(
      "rejects invalid defaultRate (%s)",
      (rate) => {
        expect(() => new RegionalTaxCalculator({}, rate)).toThrow(RangeError);
      },
    );

    it("rejects invalid rate in rates map", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 1.5 }),
      ).toThrow(RangeError);
    });

    it("accepts valid boundary rates", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 0, FR: 1 }, 0),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.20 },
      0.05,
    );

    it("uses region-specific rate", () => {
      // 10000 * 0.0875 = 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 10000 * 0.05 = 500
      expect(calc.computeTaxCents(10000, "JP")).toBe(500);
    });

    it("rounds down to nearest cent", () => {
      // 999 * 0.0875 = 87.4125 → 87
      expect(calc.computeTaxCents(999, "US-CA")).toBe(87);
    });

    it("returns 0 for zero taxable amount", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable amount", () => {
      expect(calc.computeTaxCents(-500, "US-CA")).toBe(0);
    });

    it("uses default rate of 0 when omitted", () => {
      const calc = new RegionalTaxCalculator({});
      expect(calc.computeTaxCents(10000, "US")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  const mockProvider = (rate: number): AsyncTaxRateProvider => ({
    getRate: vi.fn().mockResolvedValue(rate),
  });

  it("computes tax using async rate", async () => {
    const calc = new AsyncTaxCalculator(mockProvider(0.10));
    expect(await calc.computeTaxCents(10000, "US")).toBe(1000);
  });

  it("rounds down fractional cents", async () => {
    const calc = new AsyncTaxCalculator(mockProvider(0.0875));
    // 999 * 0.0875 = 87.4125 → 87
    expect(await calc.computeTaxCents(999, "US")).toBe(87);
  });

  it("returns 0 for zero taxable", async () => {
    const provider = mockProvider(0.10);
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    // should not even call getRate
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable", async () => {
    const calc = new AsyncTaxCalculator(mockProvider(0.10));
    expect(await calc.computeTaxCents(-500, "US")).toBe(0);
  });

  it("throws RangeError for out-of-range rate from provider", async () => {
    const calc = new AsyncTaxCalculator(mockProvider(1.5));
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative rate from provider", async () => {
    const calc = new AsyncTaxCalculator(mockProvider(-0.1));
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate from provider", async () => {
    const calc = new AsyncTaxCalculator(mockProvider(NaN));
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network failure")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
      "network failure",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight across multiple lines", () => {
    const lines: CartLine[] = [
      line(2, { weightGrams: 500 }),
      line(3, { weightGrams: 200 }),
    ];
    // 2*500 + 3*200 = 1600
    expect(totalLineWeightGrams(lines)).toBe(1600);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [line(5)];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty array", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

