import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
  type WeightBracket,
} from "../src/shipping.ts";
import type { CartLine, Product } from "../src/product.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

const line = (qty: number, overrides: Partial<Product> = {}): CartLine => ({
  product: product(overrides),
  quantity: qty,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([line(1)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(10.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.9)).toThrow(RangeError);
    });

    it("accepts valid parameters", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns flat fee for non-empty cart without threshold", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([line(1)], 3000)).toBe(799);
    });

    it("returns flat fee when subtotal below threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([line(1)], 4999)).toBe(500);
    });

    it("returns 0 when subtotal equals threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([line(1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([line(1)], 10000)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 2000, costCents: 600 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: 10.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects invalid overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(brackets, -1),
      ).toThrow(RangeError);
      expect(
        () => new WeightBasedShippingCalculator(brackets, 10.5),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      expect(calc.computeShippingCents([line(2)], 5000)).toBe(0);
    });

    it("selects first bracket for weight within it", () => {
      // 1 * 300g = 300g → first bracket (up to 500)
      const lines = [line(1, { weightGrams: 300 })];
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // exactly 500g → first bracket boundary
      const lines = [line(1, { weightGrams: 500 })];
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      // 501g → second bracket (up to 2000)
      const lines = [line(1, { weightGrams: 501 })];
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });

    it("selects last bracket at its boundary", () => {
      // exactly 5000g → third bracket
      const lines = [line(1, { weightGrams: 5000 })];
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("falls back to heaviest bracket cost when no overflowCostCents", () => {
      // 6000g > 5000g → overflow → last bracket cost
      const lines = [line(1, { weightGrams: 6000 })];
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("uses overflowCostCents when provided", () => {
      const calcOverflow = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [line(1, { weightGrams: 6000 })];
      expect(calcOverflow.computeShippingCents(lines, 5000)).toBe(2000);
    });

    it("sums weight across multiple lines", () => {
      // 2 * 300g + 1 * 400g = 1000g → second bracket (up to 2000)
      const lines = [
        line(2, { id: "a", weightGrams: 300 }),
        line(1, { id: "b", weightGrams: 400 }),
      ];
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unordered: WeightBracket[] = [
        { upToGrams: 2000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ];
      const calc2 = new WeightBasedShippingCalculator(unordered);
      const lines = [line(1, { weightGrams: 400 })];
      expect(calc2.computeShippingCents(lines, 5000)).toBe(300);
    });
  });
});

