import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import { RegionalTaxCalculator, NoTaxCalculator } from "../src/tax.ts";
import {
  FlatShippingCalculator,
  FreeShippingCalculator,
} from "../src/shipping.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart — line management", () => {
  it("adds a product and reflects in itemCount", () => {
    const cart = new Cart();
    cart.add(product(), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantities when adding the same product twice", () => {
    const cart = new Cart();
    const p = product();
    cart.add(p, 2);
    cart.add(p, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("rejects non-positive quantity in add", () => {
    const cart = new Cart();
    expect(() => cart.add(product(), 0)).toThrow(RangeError);
    expect(() => cart.add(product(), -1)).toThrow(RangeError);
    expect(() => cart.add(product(), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents in add", () => {
    const cart = new Cart();
    expect(() =>
      cart.add(product({ unitPriceCents: -1 }), 1),
    ).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes existing line quantity", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.remove("a")).toBe(false); // already gone
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("missing", 1)).toThrow(
      "not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product(), 1);
    expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product(), 1);
    expect(() => cart.updateQuantity("p1", 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 2);
    cart.add(product({ id: "b" }), 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    const p = product();
    cart.add(p, 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // original cart is untouched
    expect(cart.itemCount).toBe(2);
    expect(cart.totals().subtotalCents).toBe(2000);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes subtotal as sum of price*qty", () => {
    const cart = new Cart();
    cart.add(product({ id: "a", unitPriceCents: 500 }), 2);
    cart.add(product({ id: "b", unitPriceCents: 300 }), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1900); // 1000 + 900
  });

  it("returns all-zero totals for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
    });
    cart.add(product({ unitPriceCents: 1000 }), 10);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(10000);
    expect(totals.discountCents).toBe(1000);
  });

  it("clamps over-subtotal discount to subtotal", () => {
    // A mock discount that returns more than subtotal
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 999999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(product({ unitPriceCents: 100 }), 1);
    expect(cart.totals().discountCents).toBe(100);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("computes tax on the discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(2000),
      taxCalculator: new RegionalTaxCalculator({ US: 0.10 }),
      region: "US",
    });
    cart.add(product({ unitPriceCents: 1000 }), 10);
    // subtotal = 10000, discount = 2000, discounted = 8000
    // tax = 8000 * 0.10 = 800
    const totals = cart.totals();
    expect(totals.discountCents).toBe(2000);
    expect(totals.taxCents).toBe(800);
  });

  it("computes shipping against discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(4000),
      shippingCalculator: new FlatShippingCalculator(500, 5000),
    });
    cart.add(product({ unitPriceCents: 1000 }), 8);
    // subtotal = 8000, discount = 4000, discounted = 4000
    // 4000 < freeOver 5000 → 500 shipping
    const totals = cart.totals();
    expect(totals.shippingCents).toBe(500);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ US: 0.08 }),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(product({ unitPriceCents: 1000 }), 5);
    // subtotal = 5000, discount = 500, discounted = 4500
    // tax = 4500 * 0.08 = 360
    // shipping = 500
    // total = 4500 + 360 + 500 = 5360
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(5000);
    expect(totals.discountCents).toBe(500);
    expect(totals.taxCents).toBe(360);
    expect(totals.shippingCents).toBe(500);
    expect(totals.totalCents).toBe(5360);
  });

  it("defaults to NoDiscount, NoTax, FreeShipping, region US", () => {
    const cart = new Cart();
    cart.add(product({ unitPriceCents: 1000 }), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3000);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(3000);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(product(), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
